#!/usr/bin/env node
/*
 * Keeps the old finmark.org.za addresses working on the new site.
 *
 *   node scripts/build-redirects.mjs        (runs on every Netlify build, after build-knowledge.mjs)
 *
 * Writes _redirects (Netlify's redirect file) at the site root:
 *   1. Old pages (about, contacts, data portal, our-work, search, knowledge-hub listings) → their new pages.
 *   2. Every old Knowledge Hub item address (/knowledge-hub/blog/<slug> etc., taken from each item's
 *      "Old site address" in the content manager) → its new page, or the Knowledge Hub search for it.
 *   3. Catch-alls for old Knowledge Hub addresses we don't know about.
 *   4. Files that still live on the old server (/system/…, /Publications/…, the landing sites …) are fetched
 *      from LEGACY_ORIGIN behind the scenes, so their links keep working after finmark.org.za points here.
 * Anything else that isn't found shows 404.html.
 *
 * The same rules are also written for nginx (server/redirects.conf), for when the site runs on our own server:
 * see server/README.md.
 */
import { readFileSync, writeFileSync, readdirSync, existsSync, mkdirSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = join(dirname(fileURLToPath(import.meta.url)), '..');
// Where the old site's files can still be reached once finmark.org.za points at the new site.
// Ask IT to point this address at the old server (or change it to wherever the files are moved).
const LEGACY_ORIGIN = process.env.LEGACY_ORIGIN || 'https://legacy.finmark.org.za';

const readDir = d => existsSync(d) ? readdirSync(d).filter(f => f.endsWith('.json')).map(f => {
  try { return { id: f.replace(/\.json$/, ''), ...JSON.parse(readFileSync(join(d, f), 'utf8')) }; } catch { return null; }
}).filter(Boolean) : [];
const enc = s => encodeURIComponent(s).replace(/%20/g, '+');
const HUB = '/knowledge-hub/index.html';
const SADC = ['AGO', 'BWA', 'COD', 'SWZ', 'LSO', 'MDG', 'MWI', 'MUS', 'MOZ', 'NAM', 'SYC', 'ZAF', 'TZA', 'ZMB', 'ZWE'];

const lines = [], RULES = [];
const rule = (from, to, code = '301!') => { lines.push(`${from.padEnd(70)} ${to.padEnd(90)} ${code}`); RULES.push({ from, to, code }); };
const note = t => { lines.push('', `# ${t}`); RULES.push({ note: t }); };

lines.push('# Generated by scripts/build-redirects.mjs on every build. Do not edit by hand: change the script instead.');

note('Section folders: always open their index page, so links inside the page work with or without a trailing slash');
for (const d of ['knowledge-hub', 'programmes', 'countries', 'data', 'donate']) rule(`/${d}`, `/${d}/index.html`);

note('Server files are not part of the website');
rule('/server/*', '/404.html', '404!');

note('Old main pages');
rule('/about member=:member', '/about/index.html?member=:member');
rule('/about', '/about/index.html');
rule('/contacts', '/contact/index.html');
rule('/contact', '/contact/index.html');
rule('/terms-of-reference', '/terms-of-reference/index.html');
rule('/privacy-policy', '/privacy-policy/index.html');
rule('/terms-of-use', '/terms-of-use/index.html');
rule('/fsd-network', '/about/index.html');
rule('/updates', '/knowledge-hub/index.html');
for (const p of ['/login', '/sign_up', '/account', '/account/*']) rule(p, '/');

note('Data portal → Explore Data');
// Survey pages from the old portal (/data-portal/MWI/2023, /data-portal/msm-enterprises/MWI/2012) open the same survey's results
let SURVEYS = [];
try { SURVEYS = JSON.parse(readFileSync(join(ROOT, 'data/surveys/index.json'), 'utf8')).surveys.filter(x => x.data); } catch {}
for (const x of SURVEYS) {
  const to = `/data/survey.html?d=${x.s}-${x.iso}-${x.year}`;
  if (x.s === 'msme') rule(`/data-portal/msm-enterprises/${x.iso}/${x.year}`, to);
  else rule(`/data-portal/${x.iso}/${x.year}`, to);
}
// Every other FinScope country now has its own country page too
for (const iso of [...new Set(SURVEYS.map(x => x.iso))].filter(c => !SADC.includes(c))) { rule(`/data-portal/${iso}`, `/data/country.html?country=${iso}`); rule(`/data-portal/${iso}/*`, `/data/country.html?country=${iso}`); }
rule('/data-portal/msm-enterprises/*', '/data/survey.html?d=msme-ZAF');
for (const c of SADC) { rule(`/data-portal/${c}`, `/data/country.html?country=${c}`); rule(`/data-portal/${c}/*`, `/data/country.html?country=${c}`); }
for (const p of ['/data-portal', '/data-portal/*', '/region/*', '/national_surveys', '/financial_diaries', '/geospatial_data', '/data-for-financial-markets', '/data-and-analytics', '/datasets', '/datasets/*']) rule(p, '/countries/index.html');

note('Our work → Programmes and themes');
const OUR_WORK = { 'agricultural-value-chains': `${HUB}?theme=agriculture&archived=1`, 'digital-financial-services': `${HUB}?theme=digitalisation`, innovation: `${HUB}?theme=innovation&archived=1`, msmes: `${HUB}?theme=credit-msme-finance`, 'policy-and-regulation': `${HUB}?theme=policy-regulation`, 'women-and-youth': `${HUB}?theme=gender`, 'supplier-development': '/programmes/index.html' };
for (const [k, v] of Object.entries(OUR_WORK)) rule(`/our-work/${k}`, v);
rule('/our-work', '/programmes/index.html');
rule('/our-work/*', '/programmes/index.html');

note('Old search (tags and countries are understood by the Knowledge Hub)');
rule('/search tag_term=:tag', `${HUB}?tag_term=:tag`);
rule('/search', HUB);

note('Old Knowledge Hub items → their new page, or a Knowledge Hub search for them');
const items = readDir(join(ROOT, 'content/knowledge')).filter(i => !i.draft && i.title);
const ARCH = new Set(readDir(join(ROOT, 'content/themes')).filter(t => t.status === 'archived').map(t => t.slug || t.id));
const seen = new Set();
let n = 0;
for (const i of items) {
  const m = String(i.legacy_url || '').match(/^https?:\/\/(?:www\.)?finmark\.org\.za(\/knowledge-hub\/[a-z]+\/[^?#\s]+)/i);
  if (!m || seen.has(m[1])) continue;
  if (i.body && String(i.body).trim()) { seen.add(m[1]); continue; }   // served at its old address by the build (knowledge-hub/<type>/<slug>/)
  seen.add(m[1]);
  const to = i.body && String(i.body).trim() ? `/knowledge-hub/post.html?id=${i.id}` : `${HUB}?q=${enc(i.title.replace(/[^\p{L}\p{N}\s'’-]/gu, ' ').replace(/\s+/g, ' ').trim())}&sort=rel${(i.themes || []).length && i.themes.every(t => ARCH.has(t)) ? '&archived=1' : ''}`;
  rule(m[1].replace(/ /g, '%20'), to);
  n++;
}

note('Old Knowledge Hub listings, and items we have no record of');
const TYPES = { blog: 'Blog', blogs: 'Blog', articles: 'Article', interviews: 'Interview', videos: 'Video', podcasts: 'Podcast', infographics: 'Infographic', publications: 'Report,Pocket%20guide,Presentation' };
rule('/knowledge-hub/all', HUB);
for (const [k, t] of Object.entries(TYPES)) rule(`/knowledge-hub/${k}`, `${HUB}?type=${t}`);
for (const k of Object.keys(TYPES)) rule(`/knowledge-hub/${k}/:slug`, `${HUB}?q=:slug`, '301'); // not forced: pages that exist at old addresses win

note(`Files and landing sites that still live on the old server (served from ${LEGACY_ORIGIN})`);
for (const p of ['system', 'Publications', 'TOR', 'GBL', 'SADC_FI_Forum', 'Community_digitalisation', 'Gender', 'Training', 'eKYC', 'Covid', 'FSD', 'images/logos', 'images/blogs', 'ckeditor_assets', 'assets'])
  rule(`/${p}/*`, `${LEGACY_ORIGIN}/${p}/:splat`, '200');

writeFileSync(join(ROOT, '_redirects'), lines.join('\n') + '\n');

// ---------- nginx version (our own server) ----------
// Same rules for nginx. Old files are passed to "@legacy", which server/setup.sh points at the old server.
const q = v => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/\$/g, '${dollar}') + '"';
const ng = ['# Generated by scripts/build-redirects.mjs on every build (same rules as _redirects). Included by the nginx site that server/setup.sh writes.',
  '# Do not edit by hand. Query strings are passed on, so old ?member= and ?tag_term= links keep working.', ''];
const legacy = [];
const slugTypes = [];
for (const r of RULES) {
  if (r.note) { ng.push('', `# ${r.note}`); continue; }
  const { from, to, code } = r;
  if (/\s/.test(from)) continue;                                   // query-matching rules: covered by passing the query string on
  if (code.startsWith('404')) continue;
  if (code === '200') { legacy.push(from.replace(/\*$/, '')); continue; }
  const keepArgs = to.includes('?') ? '' : '$is_args$args';
  if (from.endsWith('/:slug')) { slugTypes.push(from.split('/')[2]); continue; }
  if (from.endsWith('/*')) { ng.push(`location ^~ ${q(decodeURI(from.slice(0, -1)))} { return 301 ${q(to + keepArgs)}; }`); continue; }
  ng.push(`location = ${q(decodeURI(from))} { return 301 ${q(to + keepArgs)}; }`);
}
if (slugTypes.length) ng.push('', '# Old Knowledge Hub items we have no record of: search for the words in the address',
  `location ~ ^/knowledge-hub/(${slugTypes.join('|')})/([^/]+?)/?$ { set $khq $2; try_files /knowledge-hub/$1/$2/index.html @khsearch; }`,
  `location @khsearch { return 301 "${HUB}?q=$khq"; }`);
ng.push('', '# Files and landing sites still kept by the old site: served from this server if present, otherwise fetched from the old server',
  `location ~ ^/(${legacy.map(l => l.replace(/^\/|\/$/g, '').replace(/[.]/g, '\\.')).join('|')})/ { add_header Cache-Control "no-cache" always; add_header X-Robots-Tag $finmark_robots always; try_files $uri $uri/index.html @legacy; }`);
mkdirSync(join(ROOT, 'server'), { recursive: true });
writeFileSync(join(ROOT, 'server/redirects.conf'), ng.join('\n').replace(/\$\{dollar\}/g, '$') + '\n');
console.log(`_redirects: ${lines.filter(l => l && !l.startsWith('#')).length} rules (${n} old Knowledge Hub items)`);
